// Static chrome text baked into the rendered output (web view, deck, PDF) -
// not the user's own content, which is generated by the AI directly in the
// target language (see LANGUAGE_NAMES / the "Respond in ..." instruction
// appended to AI prompts). Keep this small: it only needs to cover text
// *we* wrote, not anything the AI or the user writes.
export const LANGUAGES = ["en", "de", "da"];
export const DEFAULT_LANGUAGE = "en";

// English names, used only to instruct the AI ("Respond in German.") - kept
// separate from the native endonyms below because a language-picker button
// should always read in its own language regardless of AI-prompt wording.
export const LANGUAGE_NAMES = {
  en: "English",
  de: "German",
  da: "Danish",
};

export const NATIVE_LANGUAGE_NAMES = {
  en: "English",
  de: "Deutsch",
  da: "Dansk",
};

const STRINGS = {
  en: {
    dateLocale: "en-GB",
    builtWith: (albumTitle) => `${albumTitle} · built with Story Builder`,
    shuffleLayout: "🔀 Shuffle layout",
    morePhotos: (n) => `${n} more photos from this stop`,
    viewOn: (title, provider) => `🏔 View "${title}" on ${provider} ↗`,
    pageOf: "Page",
  },
  de: {
    dateLocale: "de-DE",
    builtWith: (albumTitle) => `${albumTitle} · erstellt mit Story Builder`,
    shuffleLayout: "🔀 Layout neu mischen",
    morePhotos: (n) => `${n} weitere Fotos von diesem Stopp`,
    viewOn: (title, provider) => `🏔 "${title}" auf ${provider} ansehen ↗`,
    pageOf: "Seite",
  },
  da: {
    dateLocale: "da-DK",
    builtWith: (albumTitle) => `${albumTitle} · lavet med Story Builder`,
    shuffleLayout: "🔀 Bland layout",
    morePhotos: (n) => `${n} flere billeder fra dette stop`,
    viewOn: (title, provider) => `🏔 Se "${title}" på ${provider} ↗`,
    pageOf: "Side",
  },
};

export function getStrings(language) {
  return STRINGS[language] || STRINGS[DEFAULT_LANGUAGE];
}

export function languageName(code) {
  return LANGUAGE_NAMES[code] || LANGUAGE_NAMES[DEFAULT_LANGUAGE];
}
